<script setup lang="ts">
import { onMounted, ref } from 'vue';
import { api, apiMessage } from '@/api/client';

interface MigrationPreview { checksum:string; sourceVersion:string; ready:boolean; plans:number; tasks:number; mainlines:number; mainlineItems:number; reflections:number; timeEntries:number; preservedOnly:number; warnings:string[]; errors:string[] }
interface MigrationHistory { importId:string; sourceVersion:string; checksum:string; status:string; createdAt:string; completedAt:string|null; rolledBackAt:string|null }

const fileName=ref(''); const payload=ref<unknown>(null); const preview=ref<MigrationPreview|null>(null); const history=ref<MigrationHistory[]>([]); const busy=ref(false); const message=ref(''); const error=ref('');
async function loadHistory(){history.value=(await api.get<MigrationHistory[]>('/migrations/legacy')).data;}
async function choose(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;fileName.value=file.name;preview.value=null;message.value='';try{payload.value=JSON.parse(await file.text());preview.value=(await api.post<MigrationPreview>('/migrations/legacy/preview',payload.value)).data;error.value=preview.value.errors.join('；');}catch(reason){payload.value=null;error.value=reason instanceof SyntaxError?'JSON 文件无法解析。':apiMessage(reason);}}
async function migrate(){if(!payload.value||!preview.value?.ready)return;busy.value=true;try{const{data}=await api.post('/migrations/legacy/import',payload.value);message.value=`迁移完成：${data.tasks} 个计划任务、${data.mainlineItems} 个主线步骤、${data.timeEntries} 条计时流水。`;error.value='';await loadHistory();}catch(reason){error.value=apiMessage(reason);}finally{busy.value=false;}}
async function rollback(item:MigrationHistory){if(!confirm('将删除这一批迁移创建的计划和主线，原始 JSON 快照仍会保留。确认继续吗？'))return;busy.value=true;try{await api.post(`/migrations/legacy/${item.importId}/rollback`);message.value='迁移已回滚，原始快照仍保存在服务器。';error.value='';await loadHistory();}catch(reason){error.value=apiMessage(reason);}finally{busy.value=false;}}
onMounted(()=>{loadHistory().catch(reason=>{error.value=apiMessage(reason);});});
</script>
<template><div class="page"><section class="page-head"><div><p class="eyebrow">SETTINGS / MIGRATION</p><h1>设置与旧数据迁移</h1></div><p>上传前先预检，确认后执行；每批迁移都可回滚并保留原始快照。</p></section><section class="section settings-grid"><div><strong class="panel-number">01</strong><h2>选择旧版 JSON</h2><p>请从旧版计划控制台重新导出备份。新版导出会携带暑假计划、吉他和项目升级主线的任务目录。</p><p>较早的备份仍可上传，但预检会明确列出只能保存在原始快照中的数据。</p></div><div class="upload-box"><label class="file-button">选择 JSON<input type="file" accept="application/json,.json" @change="choose"/></label><strong>{{fileName||'尚未选择文件'}}</strong><template v-if="preview"><div class="migration-metrics"><span>计划 <b>{{preview.plans}}</b></span><span>任务 <b>{{preview.tasks}}</b></span><span>主线 <b>{{preview.mainlines}}</b></span><span>步骤 <b>{{preview.mainlineItems}}</b></span><span>复盘 <b>{{preview.reflections}}</b></span><span>计时 <b>{{preview.timeEntries}}</b></span></div><ul v-if="preview.warnings.length" class="warning-list"><li v-for="item in preview.warnings" :key="item">{{item}}</li></ul></template><button class="btn primary" :disabled="!preview?.ready||busy" @click="migrate">{{busy?'处理中…':'确认迁移'}}</button><p v-if="message" class="success-text">{{message}}</p><p v-if="error" class="error-text">{{error}}</p></div></section><section class="section"><div class="section-title"><div><strong class="panel-number small">02</strong><h2>迁移历史</h2></div><span>{{history.length}}</span></div><div v-if="!history.length" class="empty">还没有迁移记录。</div><div v-for="item in history" :key="item.importId" class="migration-row"><div><strong>{{item.sourceVersion}}</strong><p>{{item.importId}} · {{new Date(item.createdAt).toLocaleString()}}</p></div><span class="migration-status">{{item.status}}</span><button v-if="item.status==='COMPLETED'" class="btn danger" :disabled="busy" @click="rollback(item)">回滚本批</button></div></section><section class="section"><strong class="panel-number">03</strong><h2>客户端路线</h2><div class="roadmap"><article><strong>Web</strong><p>Vue 3 当前实现，作为所有客户端的业务基准。</p></article><article><strong>Windows / macOS</strong><p>后续使用 Tauri 封装并调用同一 API。</p></article><article><strong>Android</strong><p>后续使用 Capacitor 或原生 Kotlin。</p></article><article><strong>微信小程序</strong><p>使用独立 UI 层复用账号和业务 API。</p></article></div></section></div></template>
